@page "/recipes"
@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

<h1>@(Category != null ? FormatCategory(Category) : "All Recipes")</h1>

@if (Category == null)
{
    <div class="list-group">
        <a href="recipes/appetizers" class="list-group-item list-group-item-action">🥗 Appetizers</a>
        <a href="recipes/main-courses" class="list-group-item list-group-item-action">🍝 Main Courses</a>
        <a href="recipes/desserts" class="list-group-item list-group-item-action">🍰 Desserts</a>
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item active">@FormatCategory(Category)</li>
        </ol>
    </nav>

    @foreach (var recipe in GetRecipesForCategory(Category))
    {
        <div class="card mb-3">
            <div class="card-body">
                <h5 class="card-title">@recipe.Title</h5>
                <p class="card-text">@recipe.Summary</p>
                <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
            </div>
        </div>
    }
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private string FormatCategory(string category) => category switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        _ => category
    };

    private List<RecipeSummary> GetRecipesForCategory(string category) => category switch
    {
        "appetizers" => new()
        {
            new("bruschetta", "Classic Bruschetta", "Toasted bread topped with fresh tomatoes, basil, and garlic."),
            new("spinach-dip", "Creamy Spinach Dip", "A warm, cheesy spinach dip perfect for parties."),
        },
        "main-courses" => new()
        {
            new("spaghetti-bolognese", "Spaghetti Bolognese", "A rich and hearty Italian meat sauce over pasta."),
            new("chicken-stir-fry", "Chicken Stir-Fry", "Quick and colorful stir-fry with vegetables and soy sauce."),
        },
        "desserts" => new()
        {
            new("chocolate-cake", "Chocolate Lava Cake", "Decadent chocolate cake with a molten center."),
            new("tiramisu", "Classic Tiramisu", "Layers of coffee-soaked ladyfingers and mascarpone cream."),
        },
        _ => new()
    };

    private record RecipeSummary(string Id, string Title, string Summary);
}

@page "/recipe/{RecipeId}"

<PageTitle>@(GetRecipe()?.Title ?? "Recipe") - RecipeShare</PageTitle>

@{ var recipe = GetRecipe(); }

@if (recipe == null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">Recipes</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>

    <StarRating RecipeId="@RecipeId" @rendermode="InteractiveServer" />

    <h2>Ingredients</h2>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>
}

@code {
    [Parameter]
    public string? RecipeId { get; set; }

    private RecipeData? GetRecipe() => RecipeId switch
    {
        "bruschetta" => new("Classic Bruschetta",
            new[] { "1 baguette, sliced", "4 tomatoes, diced", "Fresh basil leaves", "2 cloves garlic, minced", "Olive oil", "Salt and pepper" },
            new[] { "Preheat oven to 400°F (200°C).", "Brush baguette slices with olive oil and toast until golden.", "Mix diced tomatoes, garlic, basil, olive oil, salt, and pepper.", "Spoon tomato mixture onto toasted bread.", "Serve immediately." }),
        "spinach-dip" => new("Creamy Spinach Dip",
            new[] { "10 oz frozen spinach, thawed and drained", "8 oz cream cheese", "1/2 cup sour cream", "1 cup mozzarella cheese", "3 cloves garlic, minced" },
            new[] { "Preheat oven to 350°F (175°C).", "Mix cream cheese, sour cream, and garlic until smooth.", "Stir in spinach and half the mozzarella.", "Transfer to baking dish, top with remaining cheese.", "Bake 20-25 minutes until bubbly." }),
        "spaghetti-bolognese" => new("Spaghetti Bolognese",
            new[] { "1 lb ground beef", "1 lb spaghetti", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic", "2 tbsp olive oil", "Italian seasoning", "Salt and pepper" },
            new[] { "Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil until soft.", "Add ground beef, cook until browned.", "Add crushed tomatoes and seasonings, simmer 20 minutes.", "Serve sauce over spaghetti." }),
        "chicken-stir-fry" => new("Chicken Stir-Fry",
            new[] { "2 chicken breasts, sliced thin", "2 cups mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 cloves garlic", "Rice for serving" },
            new[] { "Mix soy sauce, sesame oil, and cornstarch for sauce.", "Stir-fry chicken in hot wok until cooked through.", "Remove chicken, stir-fry vegetables 3-4 minutes.", "Return chicken, add sauce, cook until thickened.", "Serve over rice." }),
        "chocolate-cake" => new("Chocolate Lava Cake",
            new[] { "4 oz dark chocolate", "1/2 cup butter", "2 eggs", "2 egg yolks", "1/4 cup sugar", "2 tbsp flour" },
            new[] { "Preheat oven to 425°F (220°C). Butter ramekins.", "Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into ramekins, bake 12-14 minutes.", "Invert onto plates and serve immediately." }),
        "tiramisu" => new("Classic Tiramisu",
            new[] { "6 egg yolks", "3/4 cup sugar", "1 1/4 cups mascarpone", "2 cups heavy cream", "2 cups strong espresso, cooled", "3 tbsp coffee liqueur", "Ladyfinger cookies", "Cocoa powder" },
            new[] { "Whisk egg yolks and sugar until thick and pale.", "Add mascarpone, mix until smooth.", "Whip heavy cream to stiff peaks, fold into mascarpone mixture.", "Mix espresso and coffee liqueur in a shallow dish.", "Dip ladyfingers briefly in coffee and layer in dish.", "Spread mascarpone mixture over ladyfingers. Repeat layers.", "Refrigerate 4+ hours. Dust with cocoa before serving." }),
        _ => null
    };

    private record RecipeData(string Title, string[] Ingredients, string[] Steps);
}

@rendermode InteractiveServer

<div class="my-3">
    <span class="me-2"><strong>Rate this recipe:</strong></span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "selected" : "")"
              @onclick="() => SetRating(star)"
              role="button"
              title="@star star(s)">
            @(star <= CurrentRating ? "★" : "☆")
        </span>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @CurrentRating/5</span>
    }
</div>

@code {
    [Parameter]
    public string? RecipeId { get; set; }

    private int CurrentRating { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
    }
}

.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.2s;
}

.star:hover,
.star.selected {
    color: #f5a623;
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (IsSubmitted)
{
    <div class="alert alert-success">
        <h4>Thank you!</h4>
        <p>Your recipe "<strong>@Model.Title</strong>" has been submitted successfully.</p>
        <a href="recipes" class="btn btn-primary">Browse Recipes</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => Model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Model.Ingredients"
                           placeholder="Enter each ingredient on a new line" />
            <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
            <div class="form-text">One ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps"
                           placeholder="Enter each step on a new line" />
            <ValidationMessage For="() => Model.Steps" class="text-danger" />
            <div class="form-text">One step per line.</div>
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel Model { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        IsSubmitted = true;
    }

    private void Reset()
    {
        Model = new();
        IsSubmitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = "";
    }
}

