@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

<h1>@(Category != null ? FormatCategory(Category) : "All Recipes")</h1>

@if (Category == null)
{
    <div class="list-group">
        <a href="recipes/appetizers" class="list-group-item list-group-item-action">🥗 Appetizers</a>
        <a href="recipes/main-courses" class="list-group-item list-group-item-action">🍝 Main Courses</a>
        <a href="recipes/desserts" class="list-group-item list-group-item-action">🍰 Desserts</a>
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item active">@FormatCategory(Category)</li>
        </ol>
    </nav>

    @foreach (var recipe in GetRecipesForCategory(Category))
    {
        <div class="card mb-3">
            <div class="card-body">
                <h5 class="card-title">@recipe.Title</h5>
                <p class="card-text">@recipe.Summary</p>
                <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
            </div>
        </div>
    }
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private string FormatCategory(string category) => category switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        _ => category
    };

    private List<RecipeSummary> GetRecipesForCategory(string category) => category switch
    {
        "appetizers" => new()
        {
            new("bruschetta", "Classic Bruschetta", "Toasted bread topped with fresh tomatoes, basil, and garlic."),
            new("spinach-dip", "Creamy Spinach Dip", "A warm, cheesy spinach dip perfect for parties."),
        },
        "main-courses" => new()
        {
            new("spaghetti-bolognese", "Spaghetti Bolognese", "A rich and hearty Italian meat sauce over pasta."),
            new("chicken-stir-fry", "Chicken Stir-Fry", "Quick and colorful stir-fry with vegetables and soy sauce."),
        },
        "desserts" => new()
        {
            new("chocolate-cake", "Chocolate Lava Cake", "Decadent chocolate cake with a molten center."),
            new("tiramisu", "Classic Tiramisu", "Layers of coffee-soaked ladyfingers and mascarpone cream."),
        },
        _ => new()
    };

    private record RecipeSummary(string Id, string Title, string Summary);
}

